SELECT COUNT(*) FROM users as u, posts as p, postHistory as ph, votes as v, badges as b WHERE u.Id = p.OwnerUserId AND u.Id = b.UserId AND p.Id = v.PostId AND p.Id = ph.PostId AND u.Reputation>=1 AND u.Reputation<=642 AND u.DownVotes>=0 AND p.AnswerCount>=0 AND p.CommentCount>=0 AND b."Date"<=CAST('2014-09-11 21:46:02' AS TIMESTAMP)
